// The generated `src/theme/palette/swatches.ts`: per palette, its default accent and, per mode, the colours the
// picker's cards show (ground, surface, accent and three cues). The order is the picker's order.
const HEADER =
  '// Generated by `npm run palette` (scripts/palette/) from scripts/palette/palettes.mjs. Do not edit: change the inputs and regenerate.';

const lower = (colour) => colour.toLowerCase();

const swatchOf = ({ neutrals, accents, lanes, tags }, defaultAccent) => ({
  ground: lower(neutrals.ground),
  surface: lower(neutrals.surface),
  accent: lower(accents[defaultAccent].fill),
  accepted: lower(lanes.ac.solid),
  wrong: lower(lanes.wa.solid),
  upcoming: lower(tags[0].dot),
});

export function swatchesTs(solved) {
  const entries = solved.map(({ palette, sets }) => ({
    id: palette.id,
    defaultAccent: palette.defaultAccent,
    light: swatchOf(sets.standard.light, palette.defaultAccent),
    dark: swatchOf(sets.standard.dark, palette.defaultAccent),
  }));
  return `${HEADER}
export interface PaletteSwatch {
  ground: string;
  surface: string;
  accent: string;
  accepted: string;
  wrong: string;
  upcoming: string;
}

export const PALETTE_SWATCHES = ${JSON.stringify(entries, null, 2)} as const satisfies readonly {
  id: string;
  defaultAccent: string;
  light: PaletteSwatch;
  dark: PaletteSwatch;
}[];
`;
}
